def tarif(nombre):
    if nombre >= 5:
        return nombre * 8
    return nombre * 10

def compter_utiles(noms):
    nombre = 0
    for nom in noms:
        if nom.strip() != "":
            nombre = nombre + 1
    return nombre

def maximum_ou_none(valeurs):
    if len(valeurs) == 0:
        return None
    maximum = valeurs[0]
    for valeur in valeurs:
        if valeur > maximum:
            maximum = valeur
    return maximum

def selectionner(valeurs, seuil):
    selection = []
    for valeur in valeurs:
        if valeur >= seuil:
            selection.append(valeur)
    return selection
